export function ContactInbox(){
 const {t}=useLocale();
 const [search,setSearch]=useState(''),[query,setQuery]=useState(''),[status,setStatus]=useState(''),[category,setCategory]=useState(''),[dateFrom,setDateFrom]=useState(''),[dateTo,setDateTo]=useState(''),[sort,setSort]=useState('newest'),[offset,setOffset]=useState(0),[selected,setSelected]=useState<Schemas['ContactInquiryOut']|null>(null),[note,setNote]=useState(''),[noteError,setNoteError]=useState(''),[nextStatus,setNextStatus]=useState('');
 useEffect(()=>{const timer=setTimeout(()=>setQuery(search.trim()),250);return()=>clearTimeout(timer);},[search]);
 const params=new URLSearchParams({offset:String(offset),limit:'25',sort});if(query)params.set('search',query);if(status)params.set('status',status);if(category)params.set('category',category);if(dateFrom)params.set('created_after',dateFrom);if(dateTo)params.set('created_before',dateTo);
 const q=useApi<Schemas['ContactInquiryOut'][] >(`contact/admin/inquiries?${params.toString()}`);
 const detail=useApi<{inquiry:Schemas['ContactInquiryOut'];email_notifications:{event:string;status:string;delivery_status:string|null;attempts:number}[];status_history:{action:string;at:string;admin_id:string|null}[]}>(selected?`contact/admin/inquiries/${selected.id}`:null);
 async function saveNote(event:React.FormEvent<HTMLFormElement>){event.preventDefault();if(!selected||!note.trim())return;setNoteError('');try{await api(`contact/admin/inquiries/${selected.id}/notes`,{method:'POST',body:json({note})});setNote('');detail.reload();q.reload();}catch(error){setNoteError(error instanceof Error?error.message:t('Could not save note'));}}
 async function updateStatus(){if(!selected||!nextStatus)return;try{await api(`contact/admin/inquiries/${selected.id}`,{method:'PATCH',body:json({status:nextStatus})});setNextStatus('');q.reload();detail.reload();}catch(error){setNoteError(error instanceof Error?error.message:t('Could not update status'));}}
 const ticket=detail.data?.inquiry;
 return <>
  <Heading title={t('Contact inquiries')} description="Review and manage support requests submitted to Procumaterial."/>
  <div className="contact-inbox-filters">
   <label className="contact-inbox-filter search-filter"><span>{t('Search tickets')}</span><input value={search} onChange={e=>{setSearch(e.target.value);setOffset(0);}} placeholder={t('Ticket, name, email or subject')}/></label>
   <label className="contact-inbox-filter">{t('Status')}<select className="select-control" aria-label={t('Filter by status')} value={status} onChange={e=>{setStatus(e.target.value);setOffset(0);}}><option value="">{t('All statuses')}</option>{['new','in_progress','waiting_for_user','resolved','closed'].map(v=><option key={v} value={v}>{t(v.replaceAll('_',' '))}</option>)}</select></label>
   <label className="contact-inbox-filter">{t('Category')}<select className="select-control" aria-label={t('Filter by category')} value={category} onChange={e=>{setCategory(e.target.value);setOffset(0);}}><option value="">{t('All categories')}</option>{['general_inquiry','buyer_support','supplier_support','account_verification','rfq_quotations','technical_support','other'].map(v=><option key={v} value={v}>{t(v.replaceAll('_',' '))}</option>)}</select></label>
   <label className="contact-inbox-filter">{t('From date')}<input type="date" value={dateFrom} onChange={e=>{setDateFrom(e.target.value);setOffset(0);}}/></label><label className="contact-inbox-filter">{t('To date')}<input type="date" value={dateTo} onChange={e=>{setDateTo(e.target.value);setOffset(0);}}/></label>
   <label className="contact-inbox-filter">{t('Sort')}<select className="select-control" aria-label={t('Sort order')} value={sort} onChange={e=>setSort(e.target.value)}><option value="newest">{t('Newest first')}</option><option value="oldest">{t('Oldest first')}</option></select></label>
  </div>
  <State {...q} retry={q.reload} empty={!q.loading&&!q.error&&!q.data?.length}/>
  <div className="contact-inbox-results"><DataTable rows={q.data||[]} columns={['ticket_reference','created_at','name','email','user_type','subject','status']} labels={{user_type:'Requester'}} render={{name:row=><><strong>{String(row.name||'â€”')}</strong><small>{t('Company')}: {String(row.company||'â€”')}</small></>,user_type:row=><><span>{t(String(row.user_type||'â€”'))}</span><small>{t('Category')}: {t(String(row.category||'â€”').replaceAll('_',' '))}</small></>,subject:row=><span className="contact-inbox-subject">{String(row.subject||'â€”')}</span>}} action={row=><Button variant="outline" onClick={()=>{setSelected(row as unknown as Schemas['ContactInquiryOut']);setNote('');setNextStatus('');}}>{t('View request')}</Button>}/></div>
  <div className="live-actions"><Button variant="outline" disabled={!offset||q.loading} onClick={()=>setOffset(Math.max(0,offset-25))}>{t('Previous')}</Button><Button variant="outline" disabled={q.loading||!q.data||q.data.length<25} onClick={()=>setOffset(offset+25)}>{t('Next')}</Button></div>
  {selected&&<AdminModal open className="live-dialog" aria-labelledby="contact-ticket-heading" onRequestClose={()=>setSelected(null)}><div className="live-form"><div className="panel-title"><div><h2 id="contact-ticket-heading">{selected.ticket_reference}</h2><p>{selected.subject}</p></div><Button variant="outline" onClick={()=>setSelected(null)}>{t('Close')}</Button></div>
   <State {...detail} retry={detail.reload}/><div className="form-grid"><div><b>{t('Name')}</b><p>{ticket?.name||selected.name}</p></div><div><b>{t('Email')}</b><p><a href={`mailto:${ticket?.email||selected.email}`}>{ticket?.email||selected.email}</a></p></div><div><b>{t('Company')}</b><p>{ticket?.company||selected.company||'â€”'}</p></div><div><b>{t('Phone')}</b><p>{ticket?.phone||selected.phone||'â€”'}</p></div><div><b>{t('User type')}</b><p>{ticket?.user_type||selected.user_type}</p></div><div><b>{t('Category')}</b><p>{ticket?.category||selected.category}</p></div><div className="field full"><b>{t('Message')}</b><p style={{whiteSpace:'pre-wrap',overflowWrap:'anywhere'}}>{ticket?.message||selected.message}</p></div><div><b>{t('Created')}</b><p>{ticket?.created_at||selected.created_at}</p></div></div>
   <label className="field">{t('Update status')}<select value={nextStatus||ticket?.status||selected.status} onChange={e=>setNextStatus(e.target.value)}>{['new','in_progress','waiting_for_user','resolved','closed'].map(value=><option key={value}>{value}</option>)}</select></label><Button disabled={!nextStatus||nextStatus===(ticket?.status||selected.status)} onClick={()=>void updateStatus()}>{t('Save status')}</Button>{noteError&&<p role="alert" className="notice">{noteError}</p>}
   <h3>{t('Email notifications')}</h3>{(detail.data?.email_notifications||[]).map(item=><p key={item.event}>{item.event}: {item.status} ({item.delivery_status||t('pending')}) Â· {t('Attempts')}: {item.attempts}</p>)}<h3>{t('Status history')}</h3>{(detail.data?.status_history||[]).map((item,i)=><p key={i}>{item.action} Â· {item.at} Â· {item.admin_id}</p>)}<h3>{t('Internal notes')}</h3><p style={{whiteSpace:'pre-wrap',overflowWrap:'anywhere'}}>{ticket?.internal_notes||t('No internal notes')}</p><form onSubmit={saveNote}><label className="field">{t('Add internal note')}<textarea required maxLength={5000} value={note} onChange={e=>setNote(e.target.value)}/></label><Button disabled={!note.trim()}>{t('Save note')}</Button></form>
  </div></AdminModal>}
 </>;
}
export function Verification(){
 const {t}=useLocale();
 const q=useApi<Schemas['ReviewQueue']>('organizations/admin/review/queue');const [selected,setSelected]=useState<{id:string;kind:string}>(),[notes,setNotes]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const dialog=useRef<HTMLDialogElement>(null);
 useEffect(()=>{if(selected&&!dialog.current?.open)dialog.current?.showModal();},[selected]);
 async function decide(approve:boolean){if(!selected||busy)return;setBusy(true);setError('');try{await api(`organizations/admin/review/${selected.kind}/${selected.id}`,{method:'POST',body:json({approve,notes})});setSelected(undefined);setNotes('');q.reload();}catch(e){setError(e instanceof Error?e.message:'Decision failed');}finally{setBusy(false);}}
 function downloadDocument(id:string){window.location.assign(apiUrl(`organizations/admin/review/verification/${id}/document-url`));}
 return <><Heading title={t("Company verification and claims")} description="Review legal identity and ownership evidence. Imported and admin-added suppliers remain unverified until an explicit review."/><State {...q} retry={q.reload}/><h2>{t("Verification requests")}</h2><DataTable rows={q.data?.verifications||[]} columns={['org_id','cr_number','document_key','status']} action={r=><div className="live-actions">{Boolean(r.document_key)&&<Button variant="outline" disabled={busy} onClick={()=>void downloadDocument(String(r.id))}>{t('Download evidence')}</Button>}<Button onClick={()=>setSelected({id:String(r.id),kind:'verification'})}>{t("Review")}</Button></div>}/><h2>{t("Company claims")}</h2><DataTable rows={q.data?.claims||[]} columns={['org_id','claimant_id','evidence','status']} action={r=><Button onClick={()=>setSelected({id:String(r.id),kind:'claim'})}>{t("Review")}</Button>}/>{selected&&<AdminModal ref={dialog} className="live-dialog" aria-labelledby="decision-title" onCancel={()=>setSelected(undefined)} open={!!selected} busy={busy} onRequestClose={()=>setSelected(undefined)}><h2 id="decision-title">{t("Review")} {selected.kind}</h2><label className="field">{t("Decision reason")}<textarea minLength={4} maxLength={500} value={notes} onChange={e=>setNotes(e.target.value)}/></label>{error&&<p role="alert">{error}</p>}<div className="live-actions"><Button disabled={busy||notes.trim().length<4} onClick={()=>void decide(true)}>{t("Approve")}</Button><Button disabled={busy||notes.trim().length<4} variant="destructive" onClick={()=>void decide(false)}>{t("Reject")}</Button><Button disabled={busy} variant="outline" onClick={()=>setSelected(undefined)}>{t("Cancel")}</Button></div></AdminModal>}</>;
}
type MaterialRow = Schemas['MaterialOut'] & { main_category_id?: string|null; subcategory_id?: string|null; main_category?:string|null; subcategory?:string|null; source_sn?: string|null; arabic_description?: string|null; updated_at?:string };
