export function Imports({kind}:{kind:string}){
 const {t}=useLocale();
 const q=useServerList<Schemas['ImportBatchOut']>('imports/batches','Search import history');const [uploadKind,setUploadKind]=useState(kind==='suppliers'?'suppliers':'materials');const [uploadOpen,setUploadOpen]=useState(false);const all=kind==='all';
 const showTrades=all||kind==='suppliers';const trades=useServerList<Record<string,unknown>>(showTrades?'imports/supplier-trades':null,'Search imported supplier trades');const categories=useApi<Schemas['CategoryOut'][]>(showTrades?'taxonomy/categories':null);const [tradeForms,setTradeForms]=useState<Record<string,{category_id:string;city:string}>>({});const [tradeError,setTradeError]=useState('');
 async function mapTrade(row:Record<string,unknown>){const form=tradeForms[String(row.id)];if(!form?.category_id||!form.city?.trim()){setTradeError(t('Choose an existing category and confirm a service city.'));return;}setTradeError('');try{await api(`imports/supplier-trades/${row.id}/map`,{method:'POST',body:json(form)});trades.reload();}catch(error){setTradeError(error instanceof Error?error.message:t('Could not map this supplier trade.'));}}
 return <><Heading title={all?t('Bulk Import'):kind==='materials'?t('Material Master Import'):t('Supplier Database Import')} description={all?'Import and manage client material and supplier workbooks from one place.':undefined}/>
 {all&&<section className="form-grid" aria-label={t('Bulk import sections')}>
  <article className="panel"><h2>{t('Material Master Import')}</h2><p>{t('Upload material workbooks, preview detected columns and categories, then confirm a background import.')}</p><Button onClick={()=>{setUploadKind('materials');setUploadOpen(true);}}><IconUpload size={16}/>{t('Import materials')}</Button></article>
  <article className="panel"><h2>{t('Supplier Database Import')}</h2><p>{t('Upload supplier workbooks, review contacts and source trades, then confirm a background import.')}</p><Button onClick={()=>{setUploadKind('suppliers');setUploadOpen(true);}}><IconUpload size={16}/>{t('Import suppliers')}</Button></article>
 </section>}
 {!all&&<div className="live-actions"><Button variant={uploadKind==='materials'?'default':'outline'} onClick={()=>setUploadKind('materials')}>{t('Material Master')}</Button><Button variant={uploadKind==='suppliers'?'default':'outline'} onClick={()=>setUploadKind('suppliers')}>{t('Supplier Database')}</Button><Button onClick={()=>setUploadOpen(true)}><IconUpload size={16}/>{uploadKind==='materials'?t('Import materials'):t('Import suppliers')}</Button></div>}
 {showTrades&&<section aria-label={t('Imported supplier trades awaiting category mapping')}><h2>{t('Supplier trade review')}</h2><p>{t('Map source trade descriptions to an existing category and confirm the service city. This creates a pending capability for a separate admin approval.')}</p>{trades.controls}<State {...trades} empty={!trades.loading&&!trades.error&&!trades.rows.length}/><DataTable searchable={false} paginate={false} rows={trades.rows} columns={['organization_name','trade','supplier_type','brands','location','mapping_status']} labels={{organization_name:'Supplier',supplier_type:'Supplier type',location:'Source location'}} render={{trade:row=><span style={{whiteSpace:'pre-wrap'}}>{String(row.trade||'â€”')}</span>,brands:row=><span style={{whiteSpace:'pre-wrap'}}>{String(row.brands||'â€”')}</span>}} action={row=><div className="form-grid"><label className="field">{t('Existing category')}<select value={tradeForms[String(row.id)]?.category_id||''} onChange={event=>setTradeForms(current=>({...current,[String(row.id)]:{category_id:event.target.value,city:current[String(row.id)]?.city||''}}))}><option value="">{t('Choose category')}</option>{(categories.data||[]).filter(category=>category.active).map(category=><option key={category.id} value={category.id}>{category.parent_id?`${(categories.data||[]).find(parent=>parent.id===category.parent_id)?.name_en||''} / `:''}{category.name_en}</option>)}</select></label><label className="field">{t('Confirmed service city')}<input value={tradeForms[String(row.id)]?.city||''} maxLength={100} onChange={event=>setTradeForms(current=>({...current,[String(row.id)]:{category_id:current[String(row.id)]?.category_id||'',city:event.target.value}}))} placeholder={String(row.location||t('Enter a confirmed city'))}/></label><Button type="button" disabled={!tradeForms[String(row.id)]?.category_id||!tradeForms[String(row.id)]?.city?.trim()} onClick={()=>void mapTrade(row)}>{t('Map for review')}</Button></div>}/>{tradeError&&<p className="notice" role="alert">{tradeError}</p>}</section>}
 <ImportUpload path={`imports/${uploadKind}`} open={uploadOpen} onClose={()=>setUploadOpen(false)} onDone={q.reload}/><section aria-label={t('Import history')}><h2>{t('Import history')}</h2>{q.controls}<State {...q}/><DataTable paginate={false} rows={q.rows} columns={['filename','kind','status','rows','created','errors','created_at']}/></section></>;
}
export {default as AdminMembership} from './memberships';
